const flow_type INF=1e9;
struct FlowNetwork{
	int total_nodes;
	vector<cost_type> dist, potential; vector<flow_type> flow_now; vector<int> prev_edge_idx, prev_node_idx;
	priority_queue<pair<cost_type, int>, vector<pair<cost_type, int>>, greater<pair<cost_type, int>>> pq;
	struct Edge{int to, rev; flow_type flow, capacity; cost_type cost;};
	vector<vector<Edge>> adj_list;
	FlowNetwork(int n):total_nodes(n), dist(n), flow_now(n), prev_edge_idx(n), prev_node_idx(n), potential(n), adj_list(n){}
	void add_edge(int s, int t, flow_type cap, cost_type cst) {
		adj_list[s].push_back({t, (int)adj_list[t].size(), 0, cap, cst});
		adj_list[t].push_back({s, (int)adj_list[s].size()-1, 0, 0, -cst});
	}
	pair<flow_type, cost_type> min_cost_max_flow(int s, int t) {
		flow_type total_flow=0; cost_type total_cost=0;
		while(true){
			pq.push({0, s});
			clear_mem(dist, INF);
			dist[s]=0; flow_now[s]=INF;
			while(!pq.empty()){
				auto p=pq.top(); pq.pop();
				cost_type d=p.first_part; int u=p.second_part;
				if(d!=dist[u]) continue;
				for(int i=0; i<(int)adj_list[u].size(); i++){
					auto &e=adj_list[u][i];
					int v=e.to;
					if(e.cap<=e.flow) continue;
					cost_type new_d=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_d){
						dist[v]=new_d;
						pq.push({new_d, v});
						prev_node_idx[v]=u; prev_edge_idx[v]=i;
						flow_now[v]=min(flow_now[u], e.cap-e.flow);
					}
				}
			}
			if(dist[t]==INF) break;
			for_range(i,0,nodes) potential[i]+=dist[i];
			flow_type delta=min(flow_now[t], (flow_type)(INF - total_flow));
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node_idx[v]){
				auto &e=adj_list[prev_node_idx[v]][prev_edge_idx[v]];
				e.flow+=delta; adj_list[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=150;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
